def caesar_cipher(text: str, shift: int) -> str:
    result = []
    for char in text:
        if 'a' <= char <= 'z':
            # Handle lowercase letters
            shifted = ord(char) + shift
            while shifted > ord('z'):
                shifted -= 26
            while shifted < ord('a'):
                shifted += 26
            result.append(chr(shifted))
        elif 'A' <= char <= 'Z':
            # Handle uppercase letters
            shifted = ord(char) + shift
            while shifted > ord('Z'):
                shifted -= 26
            while shifted < ord('A'):
                shifted += 26
            result.append(chr(shifted))
        else:
            # Leave non-alphabetic characters unchanged
            result.append(char)
    return ''.join(result)
