def word_frequency(text: str) -> dict[str, int]:
    if not text:
        return {}

    words = text.split()
    frequency = {}

    for word in words:
        # Strip punctuation from edges and convert to lowercase
        cleaned_word = word.strip('.,!?;:"\'-()[]{}').lower()

        # Skip empty strings after cleaning
        if cleaned_word:
            frequency[cleaned_word] = frequency.get(cleaned_word, 0) + 1

    return frequency
